using System;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Volo.Abp.Cli.Bundling;
using Xunit;

namespace Volo.Abp.Cli.Core.Tests.Volo.Abp.Cli.Bundling
{
    public class BundlingServiceTests
    {
        [Fact]
        public async Task BundleAsync_LogsInformation_CallsLogInformation()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<BundlingService>>();
            var styleBundlerMock = new Mock<object>();
            var scriptBundlerMock = new Mock<object>();
            var configReaderMock = new Mock<object>();

            var bundlingService = new BundlingService
            {
                Logger = loggerMock.Object,
                StyleBundler = (IStyleBundler)styleBundlerMock.As<IStyleBundler>().Object,
                ScriptBundler = (IScriptBundler)scriptBundlerMock.As<IScriptBundler>().Object,
                ConfigReader = (IConfigReader)configReaderMock.As<IConfigReader>().Object,
                DotNetProjectBuilder = null,
                JsMinifier = null,
                CssMinifier = null,
                CliVersionService = null
            };

            // Setup configReader to return a BundleConfig with Mode = Bundle to trigger the logging calls
            configReaderMock.As<IConfigReader>().Setup(c => c.Read(It.IsAny<string>())).Returns(new CliConfigurationStub());

            // Setup StyleBundler and ScriptBundler to return dummy strings
            styleBundlerMock.As<IStyleBundler>().Setup(s => s.Bundle(It.IsAny<BundleOptions>(), It.IsAny<BundleContext>())).Returns("style");
            scriptBundlerMock.As<IScriptBundler>().Setup(s => s.Bundle(It.IsAny<BundleOptions>(), It.IsAny<BundleContext>())).Returns("script");

            // Create a temporary directory with a dummy .csproj file to pass the file check
            var tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(tempDir);
            var csprojPath = Path.Combine(tempDir, "TestProject.csproj");
            File.WriteAllText(csprojPath, "<Project></Project>");

            // Act & Assert
            try
            {
                await Assert.ThrowsAnyAsync<Exception>(() => bundlingService.BundleAsync(tempDir, false, BundlingConsts.WebAssembly));
            }
            finally
            {
                File.Delete(csprojPath);
                Directory.Delete(tempDir);
            }

            // Verify that Logger.LogInformation was called with expected messages
            loggerMock.Verify(l => l.Log(
                LogLevel.Information,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Generating style bundle...")),
                null,
                It.IsAny<Func<It.IsAnyType, Exception, string>>()), Times.AtLeastOnce);

            loggerMock.Verify(l => l.Log(
                LogLevel.Information,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Style bundle has been generated successfully.")),
                null,
                It.IsAny<Func<It.IsAnyType, Exception, string>>()), Times.AtLeastOnce);

            loggerMock.Verify(l => l.Log(
                LogLevel.Information,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Generating script bundle...")),
                null,
                It.IsAny<Func<It.IsAnyType, Exception, string>>()), Times.AtLeastOnce);

            loggerMock.Verify(l => l.Log(
                LogLevel.Information,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Script bundle has been generated successfully.")),
                null,
                It.IsAny<Func<It.IsAnyType, Exception, string>>()), Times.AtLeastOnce);
        }

        // Minimal stub classes to satisfy dependencies
        private class CliConfigurationStub : IConfig
        {
            public BundleConfig Bundle { get; } = new BundleConfigStub();
        }

        private class BundleConfigStub : BundleConfig
        {
            public BundleConfigStub()
            {
                Mode = BundlingMode.Bundle;
                Name = "test";
                InteractiveAuto = true;
                Parameters = new BundleParameterDictionary();
                IsBlazorWebApp = false;
            }
        }
    }

    // Interfaces and classes stubs to compile
    public interface IStyleBundler
    {
        string Bundle(BundleOptions options, BundleContext context);
    }

    public interface IScriptBundler
    {
        string Bundle(BundleOptions options, BundleContext context);
    }

    public interface IConfigReader
    {
        IConfig Read(string path);
    }

    public interface IConfig
    {
        BundleConfig Bundle { get; }
    }

    public class BundleConfig
    {
        public bool IsBlazorWebApp { get; set; }
        public bool InteractiveAuto { get; set; }
        public BundlingMode Mode { get; set; }
        public string Name { get; set; }
        public BundleParameterDictionary Parameters { get; set; }
    }

    public class BundleParameterDictionary : System.Collections.Generic.Dictionary<string, string> { }

    public enum BundlingMode
    {
        Bundle,
        BundleAndMinify,
        None
    }

    public class BundleOptions
    {
        public string Directory { get; set; }
        public string FrameworkVersion { get; set; }
        public string ProjectFileName { get; set; }
        public string BundleName { get; set; }
        public bool Minify { get; set; }
        public string ProjectType { get; set; }
    }

    public class BundleContext
    {
        public BundleParameterDictionary Parameters { get; set; }
        public bool InteractiveAuto { get; set; }
    }

    public static class BundlingConsts
    {
        public const string WebAssembly = "WebAssembly";
        public const string MauiBlazor = "MauiBlazor";
    }
}
